@torch.no_grad()
def update_bias(moes, rate=0.001):          # Algorithm 1, after opt.step()
    vio = []
    for m in moes:
        c = m.counts.float()
        m.bias += rate * torch.sign(c.mean() - c)
        vio.append(((c.max() - c.mean()) / c.mean()).item())   # MaxVio
    return vio

